import json

def client(response, fallback="local_model"):
    if response["status"] != 200:
        return {"model": fallback, "reason": "service_error"}
    try:
        body = json.loads(response["body"])
    except (json.JSONDecodeError, TypeError):
        return {"model": fallback, "reason": "invalid_json"}
    if not isinstance(body, dict) or not isinstance(body.get("model"), str) or not body["model"].strip():
        return {"model": fallback, "reason": "missing_model"}
    return {"model": body["model"], "reason": "accepted"}

