def accuracy(predictions, expected):
    if not expected:
        return None
    correct = sum(pred == want for pred, want in zip(predictions, expected))
    return correct / len(expected)

def evaluate(data):
    expected = [task["expected"] for task in data["tasks"]]
    result = {}
    for name, model in data["models"].items():
        correct = sum(pred == want for pred, want in zip(model["predictions"], expected))
        result[name] = {"correct": correct, "total": len(expected), "accuracy": accuracy(model["predictions"], expected),
                        "latency_ms": model["latency_ms"], "cost_usd": model["cost_usd"],
                        "failed_ids": [task["id"] for i, task in enumerate(data["tasks"]) if model["predictions"][i] != task["expected"]]}
    return result

